-- Reconstructed from current Servora contracts; NOT an original database export.
CREATE TYPE public.order_type AS ENUM ('dine_in','takeout','delivery');
CREATE TYPE public.order_status AS ENUM ('new','confirmed','in_prep','ready','delivered','cancelled');
CREATE TABLE public.menu_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), client_id text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, UNIQUE(org_id,client_id), UNIQUE(org_id,id));
GRANT SELECT ON public.menu_categories TO authenticated; GRANT ALL ON public.menu_categories TO service_role;
ALTER TABLE public.menu_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY menu_categories_read ON public.menu_categories FOR SELECT TO authenticated USING(public.is_org_member(org_id));
CREATE TABLE public.menu_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), client_id text NOT NULL, category_id uuid, name text NOT NULL, description text NOT NULL DEFAULT '', price_cents integer NOT NULL CHECK(price_cents>=0), prep_time_minutes integer NOT NULL DEFAULT 10 CHECK(prep_time_minutes>=0), image_url text, notes text, active boolean NOT NULL DEFAULT true, location_ids uuid[] NOT NULL DEFAULT '{}', modifier_groups jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,client_id), UNIQUE(org_id,id), FOREIGN KEY(org_id,category_id) REFERENCES public.menu_categories(org_id,id));
GRANT SELECT ON public.menu_products TO authenticated; GRANT ALL ON public.menu_products TO service_role;
ALTER TABLE public.menu_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY menu_products_read ON public.menu_products FOR SELECT TO authenticated USING(public.is_org_member(org_id) AND (cardinality(location_ids)=0 OR public.is_org_owner(org_id) OR EXISTS(SELECT 1 FROM unnest(location_ids) x WHERE public.can_access_location(x))));
CREATE INDEX menu_products_org ON public.menu_products(org_id,active);
CREATE TABLE public.inventory_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), location_id uuid NOT NULL REFERENCES public.locations(id), client_id text NOT NULL, name text NOT NULL, category text NOT NULL DEFAULT 'dry_goods', sku text NOT NULL DEFAULT '', unit text NOT NULL, quantity numeric NOT NULL DEFAULT 0 CHECK(quantity>=0), min_quantity numeric NOT NULL DEFAULT 0 CHECK(min_quantity>=0), cost_cents integer NOT NULL DEFAULT 0 CHECK(cost_cents>=0), supplier text NOT NULL DEFAULT '', expiration_date date, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,location_id,client_id), UNIQUE(org_id,location_id,id));
GRANT SELECT ON public.inventory_items TO authenticated; GRANT ALL ON public.inventory_items TO service_role;
