CREATE INDEX inventory_org_store ON public.inventory_items(org_id,location_id);
CREATE TABLE public.product_recipes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), product_id uuid NOT NULL, location_id uuid NOT NULL REFERENCES public.locations(id), servings numeric NOT NULL CHECK(servings>0), yield_quantity numeric NOT NULL DEFAULT 1 CHECK(yield_quantity>0), yield_unit text NOT NULL DEFAULT 'units', instructions text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,location_id,product_id), UNIQUE(org_id,location_id,id), FOREIGN KEY(org_id,product_id) REFERENCES public.menu_products(org_id,id));
GRANT SELECT ON public.product_recipes TO authenticated; GRANT ALL ON public.product_recipes TO service_role;
ALTER TABLE public.product_recipes ENABLE ROW LEVEL SECURITY;
CREATE POLICY recipes_read ON public.product_recipes FOR SELECT TO authenticated USING(public.is_org_member(org_id) AND public.can_access_location(location_id));
CREATE TABLE public.recipe_ingredients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, location_id uuid NOT NULL, recipe_id uuid NOT NULL, inventory_item_id uuid NOT NULL, quantity numeric NOT NULL CHECK(quantity>0), unit text NOT NULL, waste_percentage numeric NOT NULL DEFAULT 0 CHECK(waste_percentage>=0 AND waste_percentage<=100), FOREIGN KEY(org_id,location_id,recipe_id) REFERENCES public.product_recipes(org_id,location_id,id), FOREIGN KEY(org_id,location_id,inventory_item_id) REFERENCES public.inventory_items(org_id,location_id,id), UNIQUE(recipe_id,inventory_item_id));
GRANT SELECT ON public.recipe_ingredients TO authenticated; GRANT ALL ON public.recipe_ingredients TO service_role;
ALTER TABLE public.recipe_ingredients ENABLE ROW LEVEL SECURITY;
CREATE POLICY ingredients_read ON public.recipe_ingredients FOR SELECT TO authenticated USING(public.is_org_member(org_id) AND public.can_access_location(location_id));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), location_id uuid NOT NULL REFERENCES public.locations(id), order_number text NOT NULL, type public.order_type NOT NULL, status public.order_status NOT NULL DEFAULT 'new', customer_name text NOT NULL DEFAULT 'Walk-in', customer_phone text, customer_email text, delivery_address text, table_number text, subtotal_cents integer NOT NULL DEFAULT 0, discount_cents integer NOT NULL DEFAULT 0, tax_rate_basis_points integer NOT NULL DEFAULT 0, tax_cents integer NOT NULL DEFAULT 0, total_cents integer NOT NULL DEFAULT 0, notes text, is_simulation boolean NOT NULL DEFAULT false, client_order_id text NOT NULL, request_hash text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(subtotal_cents>=0 AND discount_cents>=0 AND discount_cents<=subtotal_cents AND tax_cents>=0 AND total_cents>=0), CHECK(tax_rate_basis_points BETWEEN 0 AND 10000), UNIQUE(org_id,client_order_id), UNIQUE(org_id,location_id,id));
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_read ON public.orders FOR SELECT TO authenticated USING(public.is_org_member(org_id) AND public.can_access_location(location_id));
CREATE INDEX orders_org_store_date ON public.orders(org_id,location_id,created_at DESC);
CREATE INDEX orders_kds ON public.orders(org_id,location_id,status);
CREATE TABLE public.order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, location_id uuid NOT NULL, order_id uuid NOT NULL, product_id uuid NOT NULL, product_name text NOT NULL, unit_price_cents integer NOT NULL CHECK(unit_price_cents>=0), quantity integer NOT NULL CHECK(quantity>0), subtotal_cents integer NOT NULL CHECK(subtotal_cents>=0), notes text, is_item_ready boolean NOT NULL DEFAULT false, FOREIGN KEY(org_id,location_id,order_id) REFERENCES public.orders(org_id,location_id,id), FOREIGN KEY(org_id,product_id) REFERENCES public.menu_products(org_id,id));
GRANT SELECT ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role;
