CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, location_id uuid NOT NULL, order_id uuid NOT NULL UNIQUE, method text NOT NULL CHECK(method IN('cash','card','digital')), amount_cents integer NOT NULL CHECK(amount_cents>=0), status text NOT NULL DEFAULT 'recorded' CHECK(status IN('recorded','reversed')), created_at timestamptz NOT NULL DEFAULT now(), reversed_at timestamptz, FOREIGN KEY(org_id,location_id,order_id) REFERENCES public.orders(org_id,location_id,id));
