CREATE TABLE public.inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, location_id uuid NOT NULL, inventory_item_id uuid NOT NULL, order_id uuid, delta numeric NOT NULL CHECK(delta<>0), unit_cost_cents integer NOT NULL CHECK(unit_cost_cents>=0), kind text NOT NULL CHECK(kind IN('opening','adjustment','sale','reversal','receiving','transfer_in','transfer_out')), client_event_id text NOT NULL, reverses_id uuid UNIQUE REFERENCES public.inventory_movements(id), reason text NOT NULL, actor_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,client_event_id,inventory_item_id), FOREIGN KEY(org_id,location_id,inventory_item_id) REFERENCES public.inventory_items(org_id,location_id,id), FOREIGN KEY(org_id,location_id,order_id) REFERENCES public.orders(org_id,location_id,id));
