CREATE FUNCTION public.validate_operational_location() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.locations WHERE id=NEW.location_id AND org_id=NEW.org_id) THEN RAISE EXCEPTION 'invalid_location_for_org'; END IF; RETURN NEW; END $$;
CREATE TRIGGER inventory_location BEFORE INSERT OR UPDATE ON public.inventory_items FOR EACH ROW EXECUTE FUNCTION public.validate_operational_location();
CREATE TRIGGER orders_location BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.validate_operational_location();
CREATE TRIGGER finance_location BEFORE INSERT OR UPDATE ON public.finance_entries FOR EACH ROW EXECUTE FUNCTION public.validate_operational_location();
CREATE TRIGGER recipes_location BEFORE INSERT OR UPDATE ON public.product_recipes FOR EACH ROW EXECUTE FUNCTION public.validate_operational_location();
CREATE TRIGGER purchases_location BEFORE INSERT OR UPDATE ON public.purchase_orders FOR EACH ROW EXECUTE FUNCTION public.validate_operational_location();
REVOKE ALL ON FUNCTION public.validate_operational_location() FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE public.orders IS 'Reconstructed operational contract; no original records imported.';
COMMENT ON TABLE public.whatsapp_records IS 'Simulated only: no provider credentials or actual sends.';